 Lesson("N4","漫画","まんが","মাঙ্গা / কমিক","manga / comic","語彙","漫画を読みます。","まんがを よみます。","মাঙ্গা পড়ি।","I read manga."),
 Lesson("N4","世界中","せかいじゅう","সারা বিশ্ব","all over the world","語彙","世界中で使われています。","せかいじゅうで つかわれています。","সারা বিশ্বে ব্যবহৃত হয়।","It is used all over the world."),
 Lesson("N4","によって","によって","দ্বারা / অনুযায়ী","by / depending on","語彙","人によって違います。","ひとによって ちがいます。","মানুষভেদে ভিন্ন হয়।","It differs depending on the person."),
 Lesson("N4","技術","ぎじゅつ","প্রযুক্তি / কৌশল","technology / technique","語彙","新しい技術を学びます。","あたらしい ぎじゅつを まなびます。","নতুন প্রযুক্তি শিখি।","I learn new technology."),
 Lesson("N4","土地","とち","জমি","land","語彙","この土地は広いです。","この とちは ひろいです。","এই জমি বড়।","This land is large."),
 Lesson("N4","利用します","りようします","ব্যবহার করা","use","語彙","図書館を利用します。","としょかんを りようします。","লাইব্রেরি ব্যবহার করি।","I use the library."),
 Lesson("N4","アクセス","アクセス","অ্যাক্সেস / যাতায়াত সুবিধা","access","語彙","駅からのアクセスが便利です。","えきからの アクセスが べんりです。","স্টেশন থেকে যাতায়াত সুবিধাজনক।","Access from the station is convenient."),
 Lesson("N4","〜なければならない","〜なければ ならない","অবশ্যই করতে হবে","must / have to","文法"),
 Lesson("N3","経験","けいけん","অভিজ্ঞতা","experience","語彙"),
 Lesson("N3","〜ようにする","〜ように する","চেষ্টা/অভ্যাস করা যেন…","make an effort to","文法"),
 Lesson("N2","改善","かいぜん","উন্নতি / সংশোধন","improvement","語彙"),
 Lesson("N2","〜に違いない","〜に ちがいない","নিশ্চয়ই","must be / no doubt","文法"),
 Lesson("N1","遂行","すいこう","সম্পাদন / বাস্তবায়ন","execution","語彙"),
 Lesson("N1","〜を余儀なくされる","〜を よぎなくされる","বাধ্য হওয়া","be forced to","文法")
)

class MainActivity:ComponentActivity(){
 private var tts:TextToSpeech?=null
 override fun onCreate(b:Bundle?){super.onCreate(b);tts=TextToSpeech(this){if(it==TextToSpeech.SUCCESS){tts?.language=Locale.JAPAN;tts?.setSpeechRate(0.85f)}};setContent{MaterialTheme{App{txt->tts?.speak("「${txt}」",TextToSpeech.QUEUE_FLUSH,null,"jp")}}}}
 override fun onDestroy(){tts?.stop();tts?.shutdown();super.onDestroy()}
}

@Composable fun RubyText(base:String,ruby:String,modifier:Modifier=Modifier){
 Column(modifier,horizontalAlignment=Alignment.CenterHorizontally){
  Text(ruby,fontSize=12.sp,lineHeight=14.sp,textAlign=TextAlign.Center,color=MaterialTheme.colorScheme.primary)
  Text(base,fontSize=27.sp,lineHeight=32.sp,fontWeight=FontWeight.Bold,textAlign=TextAlign.Center)
 }
}

@Composable fun App(speak:(String)->Unit){
 var level by rememberSaveable{mutableStateOf("N5")}
 var query by rememberSaveable{mutableStateOf("")}
 var studyFilter by rememberSaveable{mutableStateOf("সব")}
 var contentType by rememberSaveable{mutableStateOf("語彙")}
 var infoPage by rememberSaveable{mutableStateOf("")}
 val context=LocalContext.current
 val prefs=remember{context.getSharedPreferences("study_progress",Context.MODE_PRIVATE)}
 var learnedKeys by remember{mutableStateOf(prefs.getString("learned_keys","") ?: "")}
 val learned=remember(learnedKeys){learnedKeys.split("§").filter{it.isNotBlank()}.toSet()}
 val listState=rememberLazyListState()
 Scaffold(topBar={Surface(tonalElevation=4.dp){Column(Modifier.fillMaxWidth().padding(horizontal=18.dp,vertical=14.dp)){Text("日本語マスター",fontSize=27.sp,fontWeight=FontWeight.Bold);Text("Nihongo Master বাংলা  •  JLPT N5 → N1",fontSize=13.sp)}}}){p->
  Column(Modifier.padding(p).padding(horizontal=14.dp)){
   Spacer(Modifier.height(12.dp))
   Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){AssistChip(onClick={infoPage=if(infoPage=="kana")"" else "kana"},label={Text("あ ア • Kana")});AssistChip(onClick={infoPage=if(infoPage=="about")"" else "about"},label={Text("ⓘ About")})}
   if(infoPage=="kana"){
    Card(Modifier.fillMaxWidth(),shape=RoundedCornerShape(22.dp)){Column(Modifier.padding(18.dp)){
     Text("かなを学ぼう",fontSize=25.sp,fontWeight=FontWeight.Bold)
     Text("ひらがな • カタカナ",fontSize=16.sp,color=MaterialTheme.colorScheme.primary)
     Text("একসাথে Hiragana ও Katakana শিখুন",fontSize=14.sp)
     Spacer(Modifier.height(14.dp))
     listOf(
      "あ  い  う  え  お     ア  イ  ウ  エ  オ",
      "か  き  く  け  こ     カ  キ  ク  ケ  コ",
      "が  ぎ  ぐ  げ  ご     ガ  ギ  グ  ゲ  ゴ",
      "さ  し  す  せ  そ     サ  シ  ス  セ  ソ",
      "ざ  じ  ず  ぜ  ぞ     ザ  ジ  ズ  ゼ  ゾ",
      "た  ち  つ  て  と     タ  チ  ツ  テ  ト",
      "だ  ぢ  づ  で  ど     ダ  ヂ  ヅ  デ  ド",
      "な  に  ぬ  ね  の     ナ  ニ  ヌ  ネ  ノ",
      "は  ひ  ふ  へ  ほ     ハ  ヒ  フ  ヘ  ホ",
      "ば  び  ぶ  べ  ぼ     バ  ビ  ブ  ベ  ボ",
      "ぱ  ぴ  ぷ  ぺ  ぽ     パ  ピ  プ  ペ  ポ",
      "ま  み  む  め  も     マ  ミ  ム  メ  モ",
      "や      ゆ      よ      ヤ      ユ      ヨ",
      "ら  り  る  れ  ろ     ラ  リ  ル  レ  ロ",
      "わ              を  ん   ワ              ヲ  ン"
     ).forEach{Text(it,fontSize=17.sp,lineHeight=25.sp)}
     HorizontalDivider(Modifier.padding(vertical=12.dp))
     Text("拗音 • Combined sounds",fontWeight=FontWeight.Bold)
     Text("きゃ きゅ きょ　しゃ しゅ しょ　ちゃ ちゅ ちょ",fontSize=16.sp)
     Text("キャ キュ キョ　シャ シュ ショ　チャ チュ チョ",fontSize=16.sp)
     Spacer(Modifier.height(8.dp))
     Text("促音 • ছোট っ / ッ",fontWeight=FontWeight.Bold)
     Text("きって • キット  — পরের consonant একটু থামিয়ে বলুন",fontSize=14.sp)
    }}
    Spacer(Modifier.height(10.dp))
   }
   if(infoPage=="about"){Card(Modifier.fillMaxWidth(),shape=RoundedCornerShape(18.dp)){Column(Modifier.padding(18.dp),horizontalAlignment=Alignment.CenterHorizontally){Text("Nihongo Master বাংলা",fontSize=24.sp,fontWeight=FontWeight.Bold);Text("日本語学習アプリ • Japanese Learning App");HorizontalDivider(Modifier.padding(vertical=12.dp));Text("Created by",fontWeight=FontWeight.SemiBold);Text("মোঃ খালিদ হাসান",fontSize=20.sp,fontWeight=FontWeight.Bold);Text("Md Khalid Hasan",fontSize=18.sp);Text("エムディカリドハサン",fontSize=18.sp);Spacer(Modifier.height(10.dp));Text("Developed with the assistance of AI",fontSize=13.sp)}};Spacer(Modifier.height(8.dp))}
   OutlinedTextField(query,{query=it},Modifier.fillMaxWidth(),singleLine=true,label={Text("Search • 検索")},placeholder={Text("日本語 / বাংলা / English")})
   Spacer(Modifier.height(8.dp))
   Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){listOf("N5","N4","N3","N2","N1").forEach{l->FilterChip(level==l,{level=l},{Text(l)})}}
   val levelVocab=lessons.filter{it.level==level && it.type=="語彙"}
   val learnedCount=levelVocab.count{learned.contains(it.level+"|"+it.type+"|"+it.base)}
   val kanjiLearned=if(level=="N5") n5Kanji.count{learned.contains("N5|漢字|"+it.kanji)} else 0
   val progressLabel=if(contentType=="漢字" && level=="N5") "N5 Kanji  $kanjiLearned / ${n5Kanji.size}" else "$level Vocabulary  $learnedCount / ${levelVocab.size}"
   val progressValue=if(contentType=="漢字" && level=="N5"){if(n5Kanji.isEmpty())0f else kanjiLearned.toFloat()/n5Kanji.size}else{if(levelVocab.isEmpty())0f else learnedCount.toFloat()/levelVocab.size}
   Text(progressLabel,fontSize=14.sp,fontWeight=FontWeight.SemiBold)
   LinearProgressIndicator(progress={progressValue},Modifier.fillMaxWidth())
   Row(horizontalArrangement=Arrangement.spacedBy(6.dp)){listOf("語彙","文法","漢字").forEach{t->FilterChip(contentType==t,{contentType=t},{Text(when(t){"語彙"->"Vocabulary";"文法"->"Grammar";else->"Kanji"})})}}
   if(contentType=="語彙" || (contentType=="漢字" && level=="N5")) Row(horizontalArrangement=Arrangement.spacedBy(6.dp)){listOf("সব","না-পড়া","শিখেছি").forEach{f->FilterChip(studyFilter==f,{studyFilter=f},{Text(f)})}}
   if(contentType=="語彙" || (contentType=="漢字" && level=="N5")) TextButton(onClick={studyFilter="না-পড়া"}){Text("▶ Continue • যেখানে শেষ করেছিলেন")}
   val shown=if(contentType=="漢字") emptyList() else lessons.filter{x->
    val key=x.level+"|"+x.type+"|"+x.base
    x.level==level && x.type==contentType && (query.isBlank() || listOf(x.base,x.ruby,x.bn,x.en).any{s->s.contains(query,true)}) &&
      (x.type!="語彙" || studyFilter=="সব" || (studyFilter=="শিখেছি" && learned.contains(key)) || (studyFilter=="না-পড়া" && !learned.contains(key)))
   }
   LazyColumn(state=listState,verticalArrangement=Arrangement.spacedBy(10.dp),contentPadding=PaddingValues(bottom=24.dp)){
    if(contentType=="漢字" && level=="N5"){
     val ks=n5Kanji.filter{k->val key="N5|漢字|"+k.kanji;(query.isBlank() || listOf(k.kanji,k.on,k.kun,k.bn,k.en,k.words).any{it.contains(query,true)}) && (studyFilter=="সব" || (studyFilter=="শিখেছি" && learned.contains(key)) || (studyFilter=="না-পড়া" && !learned.contains(key)))}
     items(ks,key={it.kanji}){k->
      Card(Modifier.fillMaxWidth(),shape=RoundedCornerShape(18.dp)){Column(Modifier.padding(16.dp)){
       Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween,verticalAlignment=Alignment.CenterVertically){AssistChip(onClick={},label={Text("漢字 • N5 • ${k.strokes}画")});TextButton(onClick={speak(if(k.exampleRuby.isNotBlank()) k.exampleRuby else if(k.kun!="—") k.kun.replace("・","、") else k.on.replace("・","、"))}){Text("🔊 例文")}}
       Surface(Modifier.fillMaxWidth(),shape=RoundedCornerShape(16.dp),tonalElevation=2.dp){Text(k.kanji,fontSize=64.sp,fontWeight=FontWeight.Bold,textAlign=TextAlign.Center,modifier=Modifier.padding(vertical=18.dp))}
       Spacer(Modifier.height(10.dp))
       Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){
        Surface(Modifier.weight(1f),shape=RoundedCornerShape(14.dp),tonalElevation=1.dp){Column(Modifier.padding(12.dp)){Text("音読み • On’yomi",fontWeight=FontWeight.Bold);Text(k.on,fontSize=20.sp)}}
        Surface(Modifier.weight(1f),shape=RoundedCornerShape(14.dp),tonalElevation=1.dp){Column(Modifier.padding(12.dp)){Text("訓読み • Kun’yomi",fontWeight=FontWeight.Bold);Text(k.kun,fontSize=20.sp)}}
       }
       Spacer(Modifier.height(8.dp))
       Surface(Modifier.fillMaxWidth(),shape=RoundedCornerShape(14.dp),tonalElevation=1.dp){Column(Modifier.padding(12.dp)){Text("📖 অর্থ • Meaning",fontWeight=FontWeight.Bold);Text("🇧🇩  ${k.bn}",fontSize=17.sp);Text("🇬🇧  ${k.en}",fontSize=15.sp)}}
       Spacer(Modifier.height(8.dp))
       Surface(Modifier.fillMaxWidth(),shape=RoundedCornerShape(14.dp),tonalElevation=1.dp){Column(Modifier.padding(12.dp)){Text("✏️ Stroke • ${k.strokes}画",fontWeight=FontWeight.Bold);Text("🧠 মনে রাখুন: ${k.mnemonicBn}")}}
       Spacer(Modifier.height(8.dp))
       Surface(Modifier.fillMaxWidth(),shape=RoundedCornerShape(14.dp),tonalElevation=1.dp){Column(Modifier.padding(12.dp)){Text("単語 • Useful Words",fontWeight=FontWeight.Bold);Text(k.words)}}
       Spacer(Modifier.height(8.dp))
       Surface(Modifier.fillMaxWidth(),shape=RoundedCornerShape(14.dp),tonalElevation=1.dp){Column(Modifier.padding(12.dp)){Text("例文 • Example",fontWeight=FontWeight.Bold);RubyText(k.example,k.exampleRuby,Modifier.fillMaxWidth());Text("🇧🇩  ${k.exampleBn}");Text("🇬🇧  ${k.exampleEn}")}}
       val kanjiKey="N5|漢字|"+k.kanji
       val kanjiDone=learned.contains(kanjiKey)
       TextButton(onClick={val next=learned.toMutableSet();if(kanjiDone)next.remove(kanjiKey) else next.add(kanjiKey);learnedKeys=next.joinToString("§");prefs.edit().putString("learned_keys",learnedKeys).apply()}){Text(if(kanjiDone)"✓ শিখেছি • Learned" else "○ শিখেছি / Learned")}
      }}
     }
    } else if(contentType=="漢字"){
     item{Text("এই level-এর Kanji content পরে যোগ হবে।",Modifier.padding(16.dp))}
    } else items(shown,key={it.level+"|"+it.type+"|"+it.base}){x->
    Card(Modifier.fillMaxWidth(),shape=RoundedCornerShape(18.dp)){Column(Modifier.padding(16.dp)){
     Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween,verticalAlignment=Alignment.CenterVertically){AssistChip(onClick={},label={Text(x.type+" • "+x.level)});TextButton(onClick={speak(if(x.ruby.isNotBlank()) x.ruby else x.base)}){Text("🔊 発音")}}
     RubyText(x.base,x.ruby,Modifier.fillMaxWidth())
     Spacer(Modifier.height(10.dp));Text("🇧🇩  "+x.bn,fontSize=17.sp);Text("🇬🇧  "+x.en,fontSize=15.sp)
     if(x.example.isNotBlank()){HorizontalDivider(Modifier.padding(vertical=10.dp));Text("例文 • Example",fontWeight=FontWeight.SemiBold);RubyText(x.example,x.exampleRuby,Modifier.fillMaxWidth());Text("🇧🇩  "+x.exampleBn);if(x.exampleEn.isNotBlank()) Text("🇬🇧  "+x.exampleEn)}
     if(x.type=="語彙"){val key=x.level+"|"+x.type+"|"+x.base;val done=learned.contains(key);TextButton(onClick={val next=learned.toMutableSet();if(done)next.remove(key) else next.add(key);learnedKeys=next.joinToString("§");prefs.edit().putString("learned_keys",learnedKeys).apply()}){Text(if(done)"✓ শিখেছি" else "○ শিখেছি / Learned")}}
    }}
   }}
  }
 }
}
